-- Guard: a pair whose kept row is gone is skipped.
DELETE FROM finish_fold_map WHERE keep_id NOT IN (SELECT id FROM organizations);
-- Blanks on the kept row are filled from the rows folded into it, so no web address, place or description is lost.
UPDATE organizations SET website_url = (SELECT o.website_url FROM organizations o JOIN finish_fold_map m ON m.remove_id = o.id WHERE m.keep_id = organizations.id AND COALESCE(o.website_url, '') <> '' ORDER BY o.created_at LIMIT 1) WHERE COALESCE(website_url, '') = '' AND id IN (SELECT m.keep_id FROM finish_fold_map m JOIN organizations o ON o.id = m.remove_id WHERE COALESCE(o.website_url, '') <> '');
UPDATE organizations SET state = (SELECT o.state FROM organizations o JOIN finish_fold_map m ON m.remove_id = o.id WHERE m.keep_id = organizations.id AND COALESCE(o.state, '') <> '' ORDER BY o.created_at LIMIT 1), state_name = (SELECT o.state_name FROM organizations o JOIN finish_fold_map m ON m.remove_id = o.id WHERE m.keep_id = organizations.id AND COALESCE(o.state, '') <> '' ORDER BY o.created_at LIMIT 1), lat = (SELECT o.lat FROM organizations o JOIN finish_fold_map m ON m.remove_id = o.id WHERE m.keep_id = organizations.id AND COALESCE(o.state, '') <> '' ORDER BY o.created_at LIMIT 1), lng = (SELECT o.lng FROM organizations o JOIN finish_fold_map m ON m.remove_id = o.id WHERE m.keep_id = organizations.id AND COALESCE(o.state, '') <> '' ORDER BY o.created_at LIMIT 1), geo_precision = (SELECT o.geo_precision FROM organizations o JOIN finish_fold_map m ON m.remove_id = o.id WHERE m.keep_id = organizations.id AND COALESCE(o.state, '') <> '' ORDER BY o.created_at LIMIT 1) WHERE COALESCE(state, '') = '' AND id IN (SELECT m.keep_id FROM finish_fold_map m JOIN organizations o ON o.id = m.remove_id WHERE COALESCE(o.state, '') <> '');
UPDATE organizations SET city = (SELECT o.city FROM organizations o JOIN finish_fold_map m ON m.remove_id = o.id WHERE m.keep_id = organizations.id AND COALESCE(o.city, '') <> '' AND o.state = organizations.state ORDER BY o.created_at LIMIT 1), zip = (SELECT o.zip FROM organizations o JOIN finish_fold_map m ON m.remove_id = o.id WHERE m.keep_id = organizations.id AND COALESCE(o.city, '') <> '' AND o.state = organizations.state ORDER BY o.created_at LIMIT 1), lat = (SELECT o.lat FROM organizations o JOIN finish_fold_map m ON m.remove_id = o.id WHERE m.keep_id = organizations.id AND COALESCE(o.city, '') <> '' AND o.state = organizations.state ORDER BY o.created_at LIMIT 1), lng = (SELECT o.lng FROM organizations o JOIN finish_fold_map m ON m.remove_id = o.id WHERE m.keep_id = organizations.id AND COALESCE(o.city, '') <> '' AND o.state = organizations.state ORDER BY o.created_at LIMIT 1), geo_precision = (SELECT o.geo_precision FROM organizations o JOIN finish_fold_map m ON m.remove_id = o.id WHERE m.keep_id = organizations.id AND COALESCE(o.city, '') <> '' AND o.state = organizations.state ORDER BY o.created_at LIMIT 1) WHERE COALESCE(city, '') = '' AND id IN (SELECT m.keep_id FROM finish_fold_map m JOIN organizations o ON o.id = m.remove_id JOIN organizations k ON k.id = m.keep_id WHERE COALESCE(o.city, '') <> '' AND o.state = k.state);
UPDATE organizations SET description = (SELECT o.description FROM organizations o JOIN finish_fold_map m ON m.remove_id = o.id WHERE m.keep_id = organizations.id AND COALESCE(o.description, '') <> '' ORDER BY length(o.description) DESC LIMIT 1) WHERE COALESCE(description, '') = '' AND id IN (SELECT m.keep_id FROM finish_fold_map m JOIN organizations o ON o.id = m.remove_id WHERE COALESCE(o.description, '') <> '');
UPDATE organizations SET sport = (SELECT o.sport FROM organizations o JOIN finish_fold_map m ON m.remove_id = o.id WHERE m.keep_id = organizations.id AND o.sport_key IS NOT NULL ORDER BY o.created_at LIMIT 1), sport_key = (SELECT o.sport_key FROM organizations o JOIN finish_fold_map m ON m.remove_id = o.id WHERE m.keep_id = organizations.id AND o.sport_key IS NOT NULL ORDER BY o.created_at LIMIT 1), sports_json = (SELECT o.sports_json FROM organizations o JOIN finish_fold_map m ON m.remove_id = o.id WHERE m.keep_id = organizations.id AND o.sport_key IS NOT NULL ORDER BY o.created_at LIMIT 1) WHERE sport_key IS NULL AND id IN (SELECT m.keep_id FROM finish_fold_map m JOIN organizations o ON o.id = m.remove_id WHERE o.sport_key IS NOT NULL);
-- Everything that points at a folded row moves onto the kept row.
DELETE FROM organization_data_sources WHERE organization_id IN (SELECT remove_id FROM finish_fold_map) AND EXISTS (SELECT 1 FROM organization_data_sources kept JOIN finish_fold_map ON kept.organization_id = finish_fold_map.keep_id WHERE kept.source_id = organization_data_sources.source_id AND finish_fold_map.remove_id = organization_data_sources.organization_id);
DELETE FROM organization_data_sources WHERE organization_id IN (SELECT remove_id FROM finish_fold_map) AND rowid NOT IN (SELECT MIN(ods.rowid) FROM organization_data_sources ods JOIN finish_fold_map m ON m.remove_id = ods.organization_id GROUP BY m.keep_id, ods.source_id);
UPDATE organization_data_sources SET organization_id = (SELECT keep_id FROM finish_fold_map WHERE remove_id = organization_data_sources.organization_id) WHERE organization_id IN (SELECT remove_id FROM finish_fold_map);
UPDATE programs SET organization_id = (SELECT keep_id FROM finish_fold_map WHERE remove_id = programs.organization_id) WHERE organization_id IN (SELECT remove_id FROM finish_fold_map);
UPDATE link_checks SET organization_id = (SELECT keep_id FROM finish_fold_map WHERE remove_id = link_checks.organization_id) WHERE organization_id IN (SELECT remove_id FROM finish_fold_map);
UPDATE review_queue SET organization_id = (SELECT keep_id FROM finish_fold_map WHERE remove_id = review_queue.organization_id) WHERE organization_id IN (SELECT remove_id FROM finish_fold_map);
UPDATE events SET org_id = (SELECT keep_id FROM finish_fold_map WHERE remove_id = events.org_id) WHERE org_id IN (SELECT remove_id FROM finish_fold_map);
DELETE FROM profile_favorites WHERE org_id IN (SELECT remove_id FROM finish_fold_map) AND EXISTS (SELECT 1 FROM profile_favorites kept JOIN finish_fold_map ON kept.org_id = finish_fold_map.keep_id WHERE kept.profile_id = profile_favorites.profile_id AND finish_fold_map.remove_id = profile_favorites.org_id);
UPDATE profile_favorites SET org_id = (SELECT keep_id FROM finish_fold_map WHERE remove_id = profile_favorites.org_id) WHERE org_id IN (SELECT remove_id FROM finish_fold_map);
DELETE FROM organizations WHERE id IN (SELECT remove_id FROM finish_fold_map);
DROP TABLE finish_fold_map;

